from pathlib import Path
import json
import pandas as pd

PROJECT = Path(r"E:\quant-framework")


def _load_returns(path: str) -> pd.Series:
    p = Path(path)
    if not p.exists():
        return pd.Series(dtype=float)
    rows = json.loads(p.read_text(encoding="utf-8") or "[]")
    if not rows:
        return pd.Series(dtype=float)
    df = pd.DataFrame(rows)
    if df.empty:
        return pd.Series(dtype=float)
    return pd.Series(df["return"].astype(float).values, index=pd.to_datetime(df["date"]), name="strategy")


def _load_weights(path: str) -> pd.DataFrame:
    p = Path(path)
    if not p.exists():
        return pd.DataFrame()
    rows = json.loads(p.read_text(encoding="utf-8") or "[]")
    if not rows:
        return pd.DataFrame()
    df = pd.DataFrame(rows)
    if df.empty or "date" not in df:
        return pd.DataFrame()
    df["date"] = pd.to_datetime(df["date"])
    return df.set_index("date")


def run(input, context):
    import sys
    sys.path.insert(0, str(PROJECT))
    from alphalab.store import ResultStore
    from alphalab.strategy.config import StrategyConfig

    backtest_result = input.get("backtest_result") or {}
    signal_result = input.get("signal_result") or {}
    strategy_path = Path(backtest_result.get("strategy_path") or signal_result.get("strategy_path") or PROJECT / "alphalab" / "strategies" / "momentum.yaml")
    if not strategy_path.is_absolute():
        strategy_path = PROJECT / strategy_path
    cfg = StrategyConfig.from_yaml(strategy_path)
    strategy_id = input.get("strategy_id") or cfg.name
    tags = input.get("tags") or ["pipeline"]
    notes = input.get("notes") or f"Saved by Quant Research Pipeline run_id={backtest_result.get('run_id') or signal_result.get('run_id')}"
    db_path = input.get("db_path")

    returns = _load_returns(backtest_result.get("returns_path", ""))
    weights = _load_weights(backtest_result.get("backtest_weights_path", ""))
    metrics = backtest_result.get("metrics") or {}
    config_yaml = strategy_path.read_text(encoding="utf-8")

    store = ResultStore(db_path)
    try:
        store.register_strategy(strategy_id, str(strategy_path), cfg.description)
        signal_id = None
        if signal_result.get("target_weights"):
            signal_id = store.save_signal(strategy_id, signal_result.get("as_of_date") or backtest_result.get("end_date") or pd.Timestamp.today().strftime("%Y-%m-%d"), signal_result.get("target_weights"), status="generated")
        backtest_id = store.save_backtest(config_yaml, returns, metrics, strategy_id=strategy_id, weights=weights, start_date=backtest_result.get("start_date"), end_date=backtest_result.get("end_date"), tags=tags, notes=notes)
        stats = store.stats()
    finally:
        store.close()

    run_dir = Path(backtest_result.get("run_dir") or signal_result.get("run_dir") or PROJECT / "data" / "app" / "pipeline_runs" / "manual")
    receipt_path = run_dir / "result_store_receipt.json"
    receipt = {"stage": "ResultStore", "strategy_id": strategy_id, "signal_id": signal_id, "backtest_id": backtest_id, "db_path": db_path or stats.get("path"), "store_stats": stats, "metrics": metrics}
    receipt_path.write_text(json.dumps(receipt, ensure_ascii=False, indent=2), encoding="utf-8")
    receipt["receipt_path"] = str(receipt_path)
    return receipt
